/*
 * Dev-time fallback. The production container overrides this file with one
 * generated by envsubst over runtime-config.template.js at startup. In dev
 * (npm run dev), the SPA falls back to import.meta.env.VITE_* via the
 * helper in src/lib/runtime-config.ts, so leaving this empty is correct.
 *
 * Vite's public/ directory is served as-is — this stub keeps the 200 OK
 * path quiet without baking any real config into the dev bundle.
 *
 * See audit H-08.
 */
window.__RUNTIME_CONFIG__ = window.__RUNTIME_CONFIG__ || {};
